118	// put stores the object, or returns the existing one when the same root
119	// identifier is already present. Exactly one concurrent caller observes
120	// created == true for a given object. Newly stored objects register their
121	// unique chunks in the shared block table; repeated chunks within the
122	// object and chunks shared with other objects are stored only once. The
123	// audit event for the action is appended under the same lock, so event
124	// order matches commit order; providerID is set only for remote fetches.
125	func (s *store) put(obj *object, action string, providerID *string) (stored *object, created bool) {
126		s.mu.Lock()
127		defer s.mu.Unlock()
128		if existing, ok := s.objects[obj.cid]; ok {
129			s.audit.append(objectAuditRecord(action, existing, false, providerID))
