190	// setPin pins cid with the given expiration, replacing any previous pin. It
191	// reports ok == false when the object does not exist. created is true when
192	// no valid pin was in force at now. The check and the update are atomic
193	// with respect to garbage collection.
194	func (s *store) setPin(cid string, expiresAt *time.Time, now time.Time) (created, ok bool) {
195		s.mu.Lock()
196		defer s.mu.Unlock()
197		if _, exists := s.objects[cid]; !exists {
