226	// pinEntry is one live pin in a listing.
227	type pinEntry struct {
228		cid       string
229		expiresAt *time.Time
230	}
231	
232	// listPins returns the pins in force at now, sorted by cid.
233	func (s *store) listPins(now time.Time) []pinEntry {
234		s.mu.RLock()
235		defer s.mu.RUnlock()
