326	}
327	
328	// recursivePinAt returns the record in force at now for cid, or false when
329	// none exists or the record has expired.
330	func (s *store) recursivePinAt(cid string, now time.Time) (recursivePin, bool) {
331		s.mu.RLock()
332		defer s.mu.RUnlock()
333		rp, found := s.recursivePins[cid]
334		if !found || !validRecursivePin(rp, now) {
335			return recursivePin{}, false
336		}
337		return rp, true
338	}
339	
340	// removeRecursivePin deletes the record for cid, reporting whether a valid
341	// record was in force at now. Expired records are removed lazily and
342	// reported as absent. Deletion never removes the member objects and appends
343	// no audit event.
344	func (s *store) removeRecursivePin(cid string, now time.Time) bool {
345		s.mu.Lock()
346		defer s.mu.Unlock()
347		rp, found := s.recursivePins[cid]
348		if !found || !validRecursivePin(rp, now) {
349			delete(s.recursivePins, cid)
350			return false
351		}
352		delete(s.recursivePins, cid)
353		return true
354	}
355	
356	// collectGarbage removes every object retained neither by a valid direct
357	// pin nor by a valid recursive pin record at now, or only counts them when
358	// dryRun is true. It returns the affected cids in lexical order and the sum
359	// of their body sizes. The sweep is atomic with respect to pin updates and
360	// object reads.
361	func (s *store) collectGarbage(now time.Time, dryRun bool) (cids []string, totalBytes int) {
362		s.mu.Lock()
363		defer s.mu.Unlock()
364		protected := make(map[string]bool)
365		for _, rp := range s.recursivePins {
366			if !validRecursivePin(rp, now) {
367				continue
368			}
369			for _, member := range rp.members {
370				protected[member] = true
371			}
372		}
373		cids = []string{}
374		for cid, obj := range s.objects {
375			if p, pinned := s.pins[cid]; pinned && validPin(p, now) {
376				continue
377			}
378			if protected[cid] {
379				continue
380			}
381			cids = append(cids, cid)
382			totalBytes += obj.size
383		}
384		sort.Strings(cids)
385		if !dryRun {
386			for _, cid := range cids {
387				obj := s.objects[cid]
388				delete(s.objects, cid)
389				delete(s.metadata, cid)
390				s.releaseBlocks(obj)
391			}
392			for cid, p := range s.pins {
393				if !validPin(p, now) {
394					delete(s.pins, cid)
395				}
396			}
397			for cid, rp := range s.recursivePins {
398				if !validRecursivePin(rp, now) {
399					delete(s.recursivePins, cid)
400				}
401			}
402		}
403		action := auditGCCollect
404		result := "collected"
405		if dryRun {
406			action = auditGCPreview
407			result = "previewed"
408		}
409		s.audit.append(auditRecord{
410			action:  action,
411			result:  result,
412			objects: intPtr(len(cids)),
413			bytes:   intPtr(totalBytes),
414		})
415		return cids, totalBytes
416	}
417	
418	// releaseBlocks drops the object's block references, removing any block no
419	// other live object uses. The caller must hold the write lock.
420	func (s *store) releaseBlocks(obj *object) {
421		seen := make(map[string]bool, len(obj.cids))
422		for _, c := range obj.cids {
423			if seen[c] {
424				continue
425			}
426			seen[c] = true
427			b, ok := s.blocks[c]
428			if !ok {
429				continue
430			}
431			b.refs--
432			if b.refs == 0 {
433				delete(s.blocks, c)
434			}
435		}
436	}
437	
438	// metadataRevision is one immutable metadata revision of an object. Each
439	// object's revisions are kept in commit order, so the revision number of
440	// entry i is i+1. Metadata lives in process memory only: it creates no pin,
441	// takes no part in storage statistics, bundles or the audit log, and is
442	// deleted atomically with its object by garbage collection.
443	type metadataRevision struct {
444		revision    int64
445		contentType *string
446		labels      map[string]string
447		updatedAt   time.Time
448	}
449	
450	// commitMetadata appends one metadata revision for cid when expected equals
451	// the current revision number (0 before the first write). The check and the
452	// append happen under the write lock, so exactly one of several concurrent
453	// writers carrying the same expected revision commits. The returned string
454	// is empty on success or the error code to report: object_not_found or
455	// revision_conflict. created is true for the first revision of an object.
456	func (s *store) commitMetadata(cid string, expected int64, contentType *string, labels map[string]string, now time.Time) (rev metadataRevision, created bool, code string) {
457		s.mu.Lock()
458		defer s.mu.Unlock()
459		if _, ok := s.objects[cid]; !ok {
460			return metadataRevision{}, false, "object_not_found"
461		}
462		history := s.metadata[cid]
463		if int64(len(history)) != expected {
464			return metadataRevision{}, false, "revision_conflict"
465		}
466		rev = metadataRevision{
467			revision:    expected + 1,
468			contentType: contentType,
469			labels:      labels,
470			updatedAt:   now.UTC(),
471		}
472		s.metadata[cid] = append(history, rev)
473		return rev, expected == 0, ""
474	}
475	
476	// metadataAt returns the current metadata revision for cid, or the requested
477	// historical revision when revision > 0. The returned string is empty on
478	// success or the error code to report: object_not_found, metadata_not_found
479	// or metadata_revision_not_found.
480	func (s *store) metadataAt(cid string, revision int64) (metadataRevision, string) {
481		s.mu.RLock()
482		defer s.mu.RUnlock()
483		if _, ok := s.objects[cid]; !ok {
484			return metadataRevision{}, "object_not_found"
485		}
486		history := s.metadata[cid]
487		if len(history) == 0 {
488			return metadataRevision{}, "metadata_not_found"
489		}
490		if revision == 0 {
491			return history[len(history)-1], ""
492		}
493		if revision > int64(len(history)) {
494			return metadataRevision{}, "metadata_revision_not_found"
495		}
496		return history[revision-1], ""
497	}
498	
499	// refRevision is one immutable revision of a named reference. A ref points
500	// at an object by cid but creates no pin: the target may be garbage
501	// collected while the ref history stays readable. Revisions live in
502	// process memory only, take no part in storage statistics, bundles or the
503	// audit log, and are not deleted when the target object is collected.
504	type refRevision struct {
505		revision  int64
506		cid       string
507		updatedAt time.Time
508	}
509	
510	// commitRef appends one revision for name when expected equals the current
511	// revision number (0 before the first write) and cid names a live object.
512	// The existence check, revision check and append happen under one write
513	// lock, so exactly one of several concurrent writers carrying the same
514	// expected revision commits. The returned string is empty on success or the
515	// error code to report: object_not_found or revision_conflict. created is
516	// true for the first revision of a name. A new revision is recorded even
517	// when the cid is unchanged.
518	func (s *store) commitRef(name, cid string, expected int64, now time.Time) (rev refRevision, created bool, code string) {
519		s.mu.Lock()
520		defer s.mu.Unlock()
521		if _, ok := s.objects[cid]; !ok {
522			return refRevision{}, false, "object_not_found"
523		}
524		history := s.refs[name]
525		if int64(len(history)) != expected {
526			return refRevision{}, false, "revision_conflict"
527		}
528		rev = refRevision{revision: expected + 1, cid: cid, updatedAt: now.UTC()}
529		s.refs[name] = append(history, rev)
530		return rev, expected == 0, ""
531	}
532	
533	// refAt returns the current ref revision for name, or the requested
534	// historical revision when revision > 0. The returned string is empty on
535	// success or the error code to report: ref_not_found or
536	// ref_revision_not_found. Ref metadata stays readable after the target
537	// object has been garbage collected.
538	func (s *store) refAt(name string, revision int64) (refRevision, string) {
539		s.mu.RLock()
540		defer s.mu.RUnlock()
541		history := s.refs[name]
542		if len(history) == 0 {
543			return refRevision{}, "ref_not_found"
544		}
545		if revision == 0 {
546			return history[len(history)-1], ""
547		}
548		if revision > int64(len(history)) {
549			return refRevision{}, "ref_revision_not_found"
550		}
551		return history[revision-1], ""
552	}
553	
554	// resolveRefObject resolves a ref revision and its target object against a
555	// single consistent snapshot of the store: the read lock is held across
556	// both the history lookup and the object lookup, so resolution and object
557	// reading observe the same instant. It returns the resolved revision (also
558	// when the object is gone) and the error code to report: ref_not_found,
559	// ref_revision_not_found or reference_target_missing.
560	func (s *store) resolveRefObject(name string, revision int64) (rev refRevision, obj *object, code string) {
561		s.mu.RLock()
562		defer s.mu.RUnlock()
563		history := s.refs[name]
564		if len(history) == 0 {
565			return refRevision{}, nil, "ref_not_found"
566		}
567		if revision != 0 && revision > int64(len(history)) {
568			return refRevision{}, nil, "ref_revision_not_found"
569		}
570		if revision == 0 {
571			rev = history[len(history)-1]
572		} else {
573			rev = history[revision-1]
574		}
575		obj = s.objects[rev.cid]
576		if obj == nil {
577			return rev, nil, "reference_target_missing"
578		}
579		return rev, obj, ""
580	}
581	
582	// validCID reports whether s has the "sha256:<64 lowercase hex>" shape.
583	func validCID(s string) bool {
584		if len(s) != len(cidPrefix)+64 || !strings.HasPrefix(s, cidPrefix) {
585			return false
586		}
587		for _, c := range s[len(cidPrefix):] {
588			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
589				return false
590			}
591		}
592		return true
593	}
