26	// postDeltaBundleByID handles POST /v1/delta-bundles/{cid}: export only the
27	// manifest-referenced blocks the receiver does not list in "have".
28	func (s *store) postDeltaBundleByID(w http.ResponseWriter, r *http.Request) {
29		if r.Method != http.MethodPost {
30			w.Header().Set("Allow", http.MethodPost)
31			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
32			return
