229		if !validCID(*doc.Root.CID) {
230			return invalid()
231		}
232		for _, c := range *doc.Root.Chunks {
233			if !validCID(c) {
234				return invalid()
235			}
236		}
237		blockData := make(map[string][]byte, len(*doc.Blocks))
238		for _, b := range *doc.Blocks {
239			if !validCID(*b.CID) {
240				return invalid()
241			}
242			data, err := base64.StdEncoding.DecodeString(*b.Data)
243			if err != nil {
