274		// Every carried block identifier must be the digest of its decoded bytes.
275		for cid, data := range blockData {
276			if chunkCID(data) != cid {
277				return integrity()
278			}
279		}
280	
281		cids := *doc.Root.Chunks
282		if (size == 0) != (len(cids) == 0) {
283			return integrity()
284		}
285		return &deltaContent{
