326		}
327		if total != content.size {
328			return nil, "integrity_check_failed", http.StatusUnprocessableEntity
329		}
330		if rootCID(content.size, content.cids) != content.cid {
331			return nil, "integrity_check_failed", http.StatusUnprocessableEntity
332		}
333		return &object{
334			cid:    content.cid,
335			size:   content.size,
336			chunks: chunks,
337			cids:   content.cids,
338		}, "", 0
