// non-numeric literals and fractional values as syntax errors.
func parseInt(raw json.RawMessage) (int, error) {
	if len(raw) == 0 || raw[0] == '"' {
		return 0, strconv.ErrSyntax
	}
	v, err := strconv.ParseInt(string(raw), 10, 0)
	if err != nil {
		return 0, err
	}
	return int(v), nil
}

