func TestReplicationParallelFanOut(t *testing.T) {
	h := Handler()
	up := uploadObject(t, h, []byte("fan out"))

	const n = 4
	var targets []string
	var release sync.WaitGroup
	release.Add(1)
	for range n {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			release.Wait() // all deliveries must be in flight before any answers
			w.Header().Set("Content-Type", "application/json")
			_ = json.NewEncoder(w).Encode(map[string]any{"cid": up.CID, "created": true})
		}))
		t.Cleanup(srv.Close)
		targets = append(targets, srv.URL+"/v1/bundles")
	}
	sort.Strings(targets)

	start := time.Now()
	done := make(chan struct{})
	go func() {
		rec := doReplication(t, h, up.CID, replicationBody(targets, n), "application/json", false)
		if rec.Code != http.StatusOK {
			t.Errorf("status = %d: %s", rec.Code, rec.Body.String())
		}
		close(done)
	}()
	time.Sleep(100 * time.Millisecond) // let every delivery arrive
	release.Done()
	<-done
	if elapsed := time.Since(start); elapsed > time.Duration(n)*120*time.Millisecond {
		t.Fatalf("fan-out took %v, deliveries were not parallel", elapsed)
	}
}

